/* =============================================================================
 * BUILD PROMPT - POVO AI Guidance, Next Call v1
 *
 * Contract (docs/ARCHITECTURE.md section 6):
 *   request  {request_id, participant:{...as in call prep}, call_date,
 *             assessments:[{category, point_id, text, reception, note}]}
 *   response {ok:true, objection_states:{point_id: open|resolved},
 *             summary (<=240), next_best_action (<=200)} | {ok:false, reason}
 *
 * The backend applies the deterministic revision rules (spec section 7:
 * Retained / Changed / Removed / New, reordering). The model only supplies
 * the objection open/resolved states, the summary and the next best action;
 * the backend's regex fallback covers all three.
 * ========================================================================== */
const body = ($input.first().json || {}).body || {};
const reject = (reason) => [{ json: { valid: false, reason: String(reason).slice(0, 200) } }];
const str = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();

const requestId = str(body.request_id);
if (!requestId) return reject('missing request_id');
const participant = body.participant && typeof body.participant === 'object' ? body.participant : null;
if (!participant) return reject('missing participant');
const callDate = str(body.call_date);
if (!callDate) return reject('missing call_date');

const assessments = (Array.isArray(body.assessments) ? body.assessments : [])
  .filter((a) => a && str(a.point_id))
  .map((a) => ({
    category: str(a.category).toLowerCase().replace(/s$/, ''),
    point_id: str(a.point_id),
    text: str(a.text),
    reception: a.reception,
    note: str(a.note),
  }));
if (!assessments.length) return reject('no assessments');

// Reception is stored as 0/1/2 (APP_CALL_POINT_ASSESSMENT.RECEPTION); labels are accepted too.
const RECEPTION = { 0: 'Not well received', 1: 'Moderately received', 2: 'Well received' };
function receptionLabel(r) {
  if (r === null || r === undefined || r === '') return 'not rated';
  if (RECEPTION[r] !== undefined) return RECEPTION[r];
  const s = str(r).toLowerCase();
  if (/not/.test(s)) return RECEPTION[0];
  if (/moderate/.test(s)) return RECEPTION[1];
  if (/well/.test(s)) return RECEPTION[2];
  return 'not rated';
}

const objectionIds = [];
assessments.forEach((a) => { if (a.category === 'objection' && !objectionIds.includes(a.point_id)) objectionIds.push(a.point_id); });

const name = str(participant.display_name) || 'the participant';
const role = str(participant.role_type) || 'HCP';

const SYSTEM_PROMPT = [
  'You write the next-call guidance in POVO AI Guidance, the field-sales guidance tool for POVO,',
  "Incyte's oral selective JAK1 inhibitor for moderate-to-severe hidradenitis suppurativa (HS).",
  'A POVO Sales Representative has just assessed the call of ' + callDate + ' with ' + name + ' (' + role + '). Read the ASSESSMENTS and return three things.',
  '',
  '1. objection_states: one entry for EVERY objection point_id listed under OBJECTION POINT IDS, and no others.',
  '   state is open when the note says the participant is still concerned, pushed back, was not convinced, or the note gives no sign the objection was settled.',
  '   state is resolved when the note says the objection was addressed, the participant agreed, or is now comfortable.',
  '2. summary: at most 240 characters. One or two sentences on how the call went: which messages were well received, which objections are still open, what was agreed.',
  '3. next_best_action: at most 200 characters. One concrete action for the next call, for example lead with the pillar that was well received (open with safety if safety was questioned), clear the open objection first, confirm the agreed next step.',
  '',
  'HARD RULES',
  '- Use only what is in the ASSESSMENTS. Do not invent what the participant said, agreed or asked for.',
  '- Never invent clinical claims. No efficacy or safety figures, percentages, doses, trial results or comparisons with other treatments.',
  '- Never suggest off-label use. Never repeat patient details, pricing or adverse-event details from a note.',
  '- The point texts are approved (MLR) wording. Never alter or re-word them; refer to a point by its topic instead of quoting it.',
  '- Tone: plain, professional US English, written to the rep. Name the participant. No hype, no exclamation marks, no emojis, no markdown.',
  '',
  'OUTPUT',
  'Return JSON only, with no prose and no code fences. Fields:',
  '- objection_states: array of objects with the fields point_id and state (open or resolved); empty when there are no objection point ids.',
  '- summary: string.',
  '- next_best_action: string.',
].join('\n');

const line = (label, value) => (str(value) ? '- ' + label + ': ' + str(value) : null);
const participantBlock = [
  line('Name', participant.display_name),
  line('Role', participant.role_type),
  line('Decile', participant.decile),
  line('Segment', participant.segment_short_name),
  line('Competitive focus', participant.competitive_focus_label),
  line('HS patients, last 12 months', participant.hs_patients),
  line('POVO patients', participant.povo_patients),
  line('POVO discussions', participant.povo_discussions),
].filter(Boolean).join('\n');

const assessmentBlock = assessments.map((a) => [
  '- point_id: ' + a.point_id,
  '  category: ' + a.category,
  '  point: ' + (a.text || '(free-text additional notes)'),
  a.category === 'objection' ? null : '  reception: ' + receptionLabel(a.reception),
  '  note: ' + (a.note || '(no note)'),
].filter(Boolean).join('\n')).join('\n');

const USER_PROMPT = [
  'CALL DATE: ' + callDate,
  '',
  'PARTICIPANT',
  participantBlock,
  '',
  'OBJECTION POINT IDS',
  objectionIds.length ? objectionIds.map((id) => '- ' + id).join('\n') : '- none',
  '',
  'ASSESSMENTS',
  assessmentBlock,
  '',
  'Return the JSON now.',
].join('\n');

return [{
  json: {
    valid: true,
    request_id: requestId,
    objection_ids: objectionIds,
    // Every number the summary / next best action may legitimately use.
    fact_text: [callDate, participantBlock, assessmentBlock].join(' '),
    system_prompt: SYSTEM_PROMPT.replace(/[{}]/g, ''),
    user_prompt: USER_PROMPT,
  },
}];

/* =============================================================================
 * GUARD - POVO AI Guidance, Next Call v1
 *
 * Response is exactly one of:
 *   {ok:true,  objection_states:{point_id: "open"|"resolved"},
 *              summary, next_best_action}
 *   {ok:false, reason}
 *
 * Hard failures (ok:false, the backend uses its regex fallback):
 *   - output not readable as JSON
 *   - objection_states does not cover exactly the objection point_ids given,
 *     or a state other than open / resolved
 *   - summary or next_best_action empty, or still too short after fitting
 *     (text over its limit, 240 / 200, is cut back to the last whole
 *     sentence or clause that fits instead of failing the whole call)
 *   - a claim-like number (%, mg, weeks, p-value, fold) that is not in the
 *     assessments given
 * ========================================================================== */
const ctx = $('Build Prompt').first().json;
const raw = $input.first().json || {};
const fail = (reason) => [{ json: { ok: false, reason: String(reason).slice(0, 200) } }];

function unwrap(value) {
  let v = value;
  for (let i = 0; i < 4; i += 1) {
    if (typeof v === 'string') {
      const s = v.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { v = JSON.parse(s); } catch (e) { return null; }
      continue;
    }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.output !== undefined && Object.keys(v).length <= 2) { v = v.output; continue; }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.text !== undefined && Object.keys(v).length === 1) { v = v.text; continue; }
    break;
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
}

try {
  if (raw.error) return fail('model_error: ' + (raw.error.message || raw.error));
  const out = unwrap(raw);
  if (!out) return fail('model output is not a JSON object');

  /* ------------------------------------------------ objection states -- */
  const expected = ctx.objection_ids || [];
  let entries = [];
  if (Array.isArray(out.objection_states)) {
    entries = out.objection_states.filter(Boolean).map((e) => [String(e.point_id || '').trim(), e.state]);
  } else if (out.objection_states && typeof out.objection_states === 'object') {
    entries = Object.keys(out.objection_states).map((k) => [k.trim(), out.objection_states[k]]);
  } else if (expected.length) {
    return fail('objection_states missing');
  }
  const states = {};
  for (const [id, stateRaw] of entries) {
    if (!expected.includes(id)) return fail('objection_states has unknown point_id: ' + (id || '(empty)'));
    if (states[id]) return fail('objection_states repeats point_id: ' + id);
    const state = String(stateRaw || '').trim().toLowerCase();
    if (state !== 'open' && state !== 'resolved') return fail('objection state for ' + id + ' is not open or resolved');
    states[id] = state;
  }
  const missing = expected.filter((id) => !states[id]);
  if (missing.length) return fail('objection_states missing point_id: ' + missing.join(', '));

  /* ------------------------------------------------ text fields -- */
  const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();
  const summaryRaw = clean(out.summary);
  const nbaRaw = clean(out.next_best_action);
  /* The model sometimes runs a little over the limit. Cut back to the last
   * whole sentence, then clause, that fits; fail only when nothing useful is left. */
  const fit = (text, limit) => {
    if (text.length <= limit) return text;
    const head = text.slice(0, limit);
    for (const re of [/[.!?](?=\s|$)/g, /[;:,]\s/g]) {
      let cut = -1, m;
      while ((m = re.exec(head)) !== null) cut = m.index + 1;
      if (cut >= 40) return head.slice(0, cut).replace(/[;:,]$/, '.').trim();
    }
    return '';
  };
  const summary = fit(summaryRaw, 240);
  const nba = fit(nbaRaw, 200);
  if (!summary) return fail(summaryRaw ? 'summary is ' + summaryRaw.length + ' characters and cannot be fitted to 240' : 'summary missing');
  if (!nba) return fail(nbaRaw ? 'next_best_action is ' + nbaRaw.length + ' characters and cannot be fitted to 200' : 'next_best_action missing');

  const known = new Set((String(ctx.fact_text).match(/\d[\d,]*(?:\.\d+)?/g) || []).map((t) => t.replace(/,/g, '')));
  const claimRe = /(\d[\d,]*(?:\.\d+)?)\s*(%|percent|mg|milligram|weeks?|wks?|-?fold)/gi;
  for (const text of [summary, nba]) {
    let m;
    while ((m = claimRe.exec(text)) !== null) {
      if (!known.has(m[1].replace(/,/g, ''))) return fail('claim-like number not in the assessments: ' + m[0]);
    }
    if (/\bp\s*[<=]\s*0?\.\d/i.test(text)) return fail('p-value not in the assessments');
  }

  return [{ json: { ok: true, objection_states: states, summary, next_best_action: nba } }];
} catch (e) {
  return fail('guard_error: ' + (e && e.message ? e.message : e));
}

/* MODEL FAILED
 * The LLM chain's error output: Azure OpenAI timed out, refused, or returned
 * something the Structured Output Parser could not read. Answer at once with
 * {ok:false, reason} so the backend falls back to the POC rules well inside
 * N8N_TIMEOUT_SECONDS instead of waiting for the execution to die. */
const e = $input.first().json || {};
const err = e.error;
const msg = (err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || e.message || 'model call failed';
return [{ json: { ok: false, reason: 'model_error: ' + String(msg).replace(/\s+/g, ' ').slice(0, 180) } }];

/* REJECT REQUEST
 * The request broke the webhook contract (docs/ARCHITECTURE.md section 6).
 * Answer {ok:false, reason}; the backend falls back to the POC rules. */
const r = $input.first().json || {};
return [{ json: { ok: false, reason: 'invalid_request: ' + String(r.reason || 'unknown').slice(0, 180) } }];
